import React, { useState } from 'react';
import SimpleEditor from './SimpleEditor';
import { parseEventDate } from '../data/timeline';
import { v4 as uuidv4 } from 'uuid';

const getInvType = (id, types) =>
  (types || []).find(t => t.id === id) || { id, label: id, color: '#8a8680', bg: '#f2f0ec' };

const STATUS_STYLES = {
  active: { color: '#c0392b', label: 'ACTIVE',  stamp: '#c0392b' },
  cold:   { color: '#7a6a52', label: 'COLD',    stamp: '#7a6a52' },
  closed: { color: '#2e7d5e', label: 'CLOSED',  stamp: '#2e7d5e' },
};

const LOG_TYPES = {
  opened:       { label: 'Case opened',       color: '#2c5f8a', icon: '◎' },
  evidence:     { label: 'Evidence added',    color: '#2e7d5e', icon: '⊕' },
  revised:      { label: 'Position revised',  color: '#b07d28', icon: '↺' },
  contradiction:{ label: 'Contradiction noted',color: '#c0392b', icon: '⊘' },
  insight:      { label: 'Insight',           color: '#7b3fa0', icon: '✦' },
  verdict:      { label: 'Verdict recorded',  color: '#1a5c3a', icon: '⊛' },
  note:         { label: 'Note',              color: '#8a8680', icon: '·' },
};

// ── Small reusable bits ──────────────────────────────────────────
function CopyBtn({ text }) {
  const [copied, setCopied] = useState(false);
  return (
    <button onClick={() => { navigator.clipboard?.writeText(text); setCopied(true); setTimeout(() => setCopied(false), 1500); }}
      style={{ fontSize: 10, padding: '3px 10px', borderRadius: 5, border: '1px solid var(--paper-3)', color: copied ? 'var(--green)' : 'var(--ink-4)', background: 'transparent', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
      {copied ? '✓ copied' : 'copy all'}
    </button>
  );
}

function InlineText({ value, onChange, placeholder, style, multiline }) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(value);
  const commit = () => { setEditing(false); if (draft !== value) onChange(draft); };
  if (editing) {
    const props = { autoFocus: true, value: draft, onChange: e => setDraft(e.target.value), onBlur: commit,
      onKeyDown: e => { if (!multiline && e.key === 'Enter') commit(); if (e.key === 'Escape') { setDraft(value); setEditing(false); } },
      style: { ...style, background: 'var(--paper-2)', border: '1px solid var(--accent-2)', borderRadius: 5, padding: '4px 8px', outline: 'none', fontFamily: 'inherit', fontSize: 'inherit', fontWeight: 'inherit', width: '100%', resize: multiline ? 'vertical' : 'none' } };
    return multiline ? <textarea rows={3} {...props} /> : <input {...props} />;
  }
  return (
    <div onClick={() => { setDraft(value); setEditing(true); }} title="Click to edit"
      style={{ ...style, cursor: 'text', borderBottom: '1px dashed transparent', transition: 'border-color 0.15s' }}
      onMouseEnter={e => e.currentTarget.style.borderBottomColor = 'var(--accent-2)'}
      onMouseLeave={e => e.currentTarget.style.borderBottomColor = 'transparent'}>
      {value || <span style={{ color: 'var(--ink-4)', fontStyle: 'italic' }}>{placeholder}</span>}
    </div>
  );
}

function SL({ children, action }) {
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 10, paddingBottom: 6, borderBottom: '1px solid var(--paper-3)' }}>
      <span style={{ fontSize: 10, fontWeight: 700, color: 'var(--ink-4)', letterSpacing: '0.1em', textTransform: 'uppercase', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{children}</span>
      {action && <div style={{ marginLeft: 'auto' }}>{action}</div>}
    </div>
  );
}

function TagChip({ tag, onRemove, onViewTimeline }) {
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: 11, padding: '3px 10px', borderRadius: 20, background: 'var(--paper-3)', color: 'var(--ink-2)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
      #{tag}
      {onViewTimeline && <button onClick={() => onViewTimeline(tag)} style={{ fontSize: 9, color: 'var(--ink-4)', background: 'none', border: 'none', cursor: 'pointer', padding: 0 }} onMouseEnter={e => e.currentTarget.style.color='var(--accent)'} onMouseLeave={e => e.currentTarget.style.color='var(--ink-4)'}>→</button>}
      <button onClick={onRemove} style={{ fontSize: 9, color: 'var(--ink-4)', background: 'none', border: 'none', cursor: 'pointer', padding: 0 }} onMouseEnter={e => e.currentTarget.style.color='var(--red)'} onMouseLeave={e => e.currentTarget.style.color='var(--ink-4)'}>✕</button>
    </span>
  );
}

// ── Contradiction card ───────────────────────────────────────────
function ContradictionCard({ item, onDelete }) {
  return (
    <div style={{ background: 'var(--paper-card)', border: '1px solid #c0392b33', borderLeft: '3px solid #c0392b', borderRadius: 7, padding: '10px 12px', marginBottom: 8, position: 'relative' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
        <span style={{ fontSize: 9, color: '#c0392b', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.05em', textTransform: 'uppercase' }}>⊘ Contradiction</span>
        {item.sourceA && item.sourceB && (
          <span style={{ fontSize: 10, color: 'var(--ink-4)', fontStyle: 'italic' }}>{item.sourceA} vs {item.sourceB}</span>
        )}
        <button onClick={() => onDelete(item.id)} style={{ marginLeft: 'auto', fontSize: 9, color: 'var(--ink-4)', background: 'none', border: 'none', cursor: 'pointer' }}
          onMouseEnter={e => e.currentTarget.style.color='var(--red)'} onMouseLeave={e => e.currentTarget.style.color='var(--ink-4)'}>✕</button>
      </div>
      <p style={{ fontSize: 12, color: 'var(--ink)', lineHeight: 1.65, margin: 0 }}>{item.claim}</p>
    </div>
  );
}

// ── Chain of custody log entry ───────────────────────────────────
function LogEntry({ entry }) {
  const lt = LOG_TYPES[entry.type] || LOG_TYPES.note;
  const date = new Date(entry.createdAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  return (
    <div style={{ display: 'grid', gridTemplateColumns: '20px 60px 1fr', gap: '0 8px', marginBottom: 12, alignItems: 'start' }}>
      <span style={{ color: lt.color, fontSize: 12, textAlign: 'center', paddingTop: 1 }}>{lt.icon}</span>
      <span style={{ fontSize: 9, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', paddingTop: 2, lineHeight: 1.5 }}>{date}</span>
      <div>
        <span style={{ fontSize: 9, color: lt.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.05em', display: 'block', marginBottom: 2 }}>{lt.label}</span>
        <span style={{ fontSize: 12, color: 'var(--ink-2)', lineHeight: 1.6 }}>{entry.note}</span>
      </div>
    </div>
  );
}

// ── Main ─────────────────────────────────────────────────────────
export default function InvestigationCasePage({ inv, books, events, invTypes = [], onUpdate, onDelete, onBack, onViewTimeline }) {
  const invType = getInvType(inv.type, invTypes);
  const ss      = STATUS_STYLES[inv.status] || STATUS_STYLES.active;
  const linkedBooks = books.filter(b => (inv.bookIds || []).includes(b.id));
  const isDark  = document.documentElement.getAttribute('data-theme') === 'dark';

  // New entry state
  const [newActor, setNewActor]   = useState('');
  const [newCause, setNewCause]   = useState('');
  const [newTag,   setNewTag]     = useState('');
  const [addingBook, setAddingBook] = useState(false);

  // Contradiction form
  const [newContra, setNewContra] = useState({ sourceA: '', sourceB: '', claim: '' });
  const [showContraForm, setShowContraForm] = useState(false);

  // Custody log form
  const [newLogNote, setNewLogNote] = useState('');
  const [newLogType, setNewLogType] = useState('note');

  const set = (key, val) => onUpdate({ ...inv, [key]: val, updatedAt: new Date().toISOString() });

  const addToList = (field, val, setVal) => {
    if (!val.trim()) return;
    set(field, [...(inv[field] || []), val.trim()]);
    setVal('');
  };
  const removeFromList = (field, idx) => set(field, (inv[field] || []).filter((_, i) => i !== idx));

  const toggleBook = (bookId) => {
    const has = (inv.bookIds || []).includes(bookId);
    const newBookIds   = has ? (inv.bookIds||[]).filter(id => id !== bookId) : [...(inv.bookIds||[]), bookId];
    const newBookNotes = has ? (inv.bookNotes||[]).filter(bn => bn.bookId !== bookId) : [...(inv.bookNotes||[]), { bookId, quote: '', note: '' }];
    onUpdate({ ...inv, bookIds: newBookIds, bookNotes: newBookNotes, updatedAt: new Date().toISOString() });
  };

  const updateBookNote = (bookId, field, val) =>
    set('bookNotes', (inv.bookNotes||[]).map(bn => bn.bookId === bookId ? { ...bn, [field]: val } : bn));

  const addContradiction = () => {
    if (!newContra.claim.trim()) return;
    const entry = { id: uuidv4(), ...newContra, createdAt: new Date().toISOString() };
    const updated = [...(inv.contradictions || []), entry];
    // Also log it
    const logEntry = { id: uuidv4(), type: 'contradiction', note: `${newContra.sourceA && newContra.sourceB ? `${newContra.sourceA} vs ${newContra.sourceB}: ` : ''}${newContra.claim.slice(0, 80)}`, createdAt: new Date().toISOString() };
    onUpdate({ ...inv, contradictions: updated, custodyLog: [...(inv.custodyLog||[]), logEntry], updatedAt: new Date().toISOString() });
    setNewContra({ sourceA: '', sourceB: '', claim: '' });
    setShowContraForm(false);
  };

  const removeContradiction = (id) => set('contradictions', (inv.contradictions||[]).filter(c => c.id !== id));

  const addLogEntry = () => {
    if (!newLogNote.trim()) return;
    const entry = { id: uuidv4(), type: newLogType, note: newLogNote.trim(), createdAt: new Date().toISOString() };
    // If recording verdict, also save to verdict field
    const extra = newLogType === 'verdict' ? { verdict: newLogNote.trim() } : {};
    onUpdate({ ...inv, ...extra, custodyLog: [...(inv.custodyLog||[]), entry], updatedAt: new Date().toISOString() });
    setNewLogNote('');
  };

  const relatedEvents = (events||[]).filter(e => e.tags?.some(tag => (inv.tags||[]).includes(tag)));

  // Export
  const exportText = [
    `# ${inv.caseNumber || ''} — ${inv.title}`,
    `Type: ${invType.label} · Status: ${ss.label}`,
    inv.dateRange ? `Period: ${inv.dateRange}` : '',
    '',
    inv.summary ? `## Question\n${inv.summary}` : '',
    inv.actors?.length ? `\n## Key Actors\n${inv.actors.map(a=>`- ${a}`).join('\n')}` : '',
    inv.causes?.length ? `\n## Causes\n${inv.causes.map(c=>`- ${c}`).join('\n')}` : '',
    linkedBooks.length ? `\n## Evidence\n${linkedBooks.map(book => {
      const bn = (inv.bookNotes||[]).find(n=>n.bookId===book.id)||{};
      return `### ${book.title}\n${bn.quote?`> "${bn.quote}"\n`:''}${bn.note||''}`;
    }).join('\n\n')}` : '',
    inv.contradictions?.length ? `\n## Contradictions\n${inv.contradictions.map(c=>`- [${c.sourceA} vs ${c.sourceB}] ${c.claim}`).join('\n')}` : '',
    inv.analysis ? `\n## Analysis\n${inv.analysis.replace(/<[^>]*>/g,'')}` : '',
    inv.verdict ? `\n## Verdict\n${inv.verdict}` : '',
    inv.custodyLog?.length ? `\n## Chain of Custody\n${inv.custodyLog.map(l=>`[${new Date(l.createdAt).toLocaleDateString()}] ${LOG_TYPES[l.type]?.label||l.type}: ${l.note}`).join('\n')}` : '',
  ].filter(Boolean).join('\n');

  const cardBg  = isDark ? '#272420' : '#fffdf7';
  const paperBg = isDark ? '#1e1c17' : '#faf6ee';

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', background: paperBg }}>

      {/* ── HEADER ──────────────────────────────────────────── */}
      <div style={{ padding: '12px 24px 10px', borderBottom: `2px solid ${invType.color}33`, display: 'flex', alignItems: 'center', gap: 12, flexShrink: 0, background: isDark ? '#1a1814' : '#f5f0e4' }}>
        <button onClick={onBack} style={{ fontSize: 12, color: 'var(--ink-3)', cursor: 'pointer', background: 'none', border: 'none', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>← INVESTIGATION</button>
        <div style={{ width: 1, height: 18, background: 'var(--paper-3)' }} />

        <div style={{ flex: 1 }}>
          {/* Case number */}
          <div style={{ fontSize: 10, color: invType.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.1em', marginBottom: 2 }}>
            <InlineText value={inv.caseNumber || ''} onChange={val => set('caseNumber', val)}
              placeholder="CASE-XXXX"
              style={{ fontSize: 10, color: invType.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.1em', display: 'inline' }} />
          </div>
          {/* Title */}
          <InlineText value={inv.title} onChange={val => set('title', val)} placeholder="Case title…"
            style={{ fontSize: 18, fontWeight: 700, color: 'var(--ink)', letterSpacing: '-0.01em' }} />
          <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginTop: 3 }}>
            <select value={inv.type || ''} onChange={e => set('type', e.target.value)}
              style={{ fontSize: 10, padding: '2px 22px 2px 8px', borderRadius: 4, background: invType.color + '22', color: invType.color, border: `1px solid ${invType.color}44`, fontFamily: 'var(--font-mono)', fontStyle: 'normal', cursor: 'pointer' }}>
              {invTypes.map(t => <option key={t.id} value={t.id}>{t.label}</option>)}
            </select>
            <InlineText value={inv.dateRange || ''} onChange={val => set('dateRange', val)} placeholder="period…"
              style={{ fontSize: 11, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }} />
          </div>
        </div>

        {/* Status stamp */}
        <div style={{ textAlign: 'center', flexShrink: 0 }}>
          <div style={{ border: `3px solid ${ss.stamp}`, borderRadius: 6, padding: '4px 12px', transform: 'rotate(-4deg)', display: 'inline-block', opacity: 0.85 }}>
            <div style={{ fontSize: 14, fontWeight: 900, color: ss.stamp, fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.1em' }}>{ss.label}</div>
          </div>
          <div style={{ display: 'flex', gap: 3, marginTop: 5, justifyContent: 'center' }}>
            {Object.entries(STATUS_STYLES).map(([k, v]) => (
              <button key={k} onClick={() => set('status', k)}
                style={{ fontSize: 9, padding: '1px 6px', borderRadius: 3, background: inv.status===k?v.stamp+'33':'transparent', color: inv.status===k?v.stamp:'var(--ink-4)', border: `1px solid ${inv.status===k?v.stamp:'var(--paper-3)'}`, cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
                {v.label}
              </button>
            ))}
          </div>
        </div>

        <CopyBtn text={exportText} />
        <button onClick={() => { if (window.confirm('Delete this case?')) { onDelete?.(inv.id); onBack(); } }}
          style={{ fontSize: 10, padding: '3px 10px', borderRadius: 5, border: '1px solid var(--paper-3)', color: 'var(--ink-4)', background: 'transparent', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}
          onMouseEnter={e => { e.currentTarget.style.color='var(--red)'; e.currentTarget.style.borderColor='var(--red)'; }}
          onMouseLeave={e => { e.currentTarget.style.color='var(--ink-4)'; e.currentTarget.style.borderColor='var(--paper-3)'; }}>
          delete
        </button>
      </div>

      {/* ── BODY: 4 columns ─────────────────────────────────── */}
      <div style={{ flex: 1, overflow: 'hidden', display: 'grid', gridTemplateColumns: '1fr 260px 260px 260px' }}>

        {/* COL 1 — Case details */}
        <div style={{ overflowY: 'auto', padding: '18px 20px', borderRight: `1px solid ${invType.color}22` }}>

          {/* Opening question */}
          <div style={{ background: cardBg, border: `1px solid ${invType.color}33`, borderLeft: `4px solid ${invType.color}`, borderRadius: 8, padding: '14px 16px', marginBottom: 20, boxShadow: '2px 2px 6px rgba(0,0,0,0.06)' }}>
            <div style={{ fontSize: 10, fontWeight: 700, color: invType.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 8 }}>◉ Opening question</div>
            <InlineText value={inv.summary||''} onChange={val => set('summary', val)} placeholder="What is the central question?" multiline
              style={{ fontSize: 14, color: 'var(--ink)', lineHeight: 1.75, fontStyle: 'italic' }} />
          </div>

          {/* Key actors */}
          <div style={{ marginBottom: 20 }}>
            <SL>Key actors</SL>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 8 }}>
              {(inv.actors||[]).map((a,i) => (
                <span key={i} style={{ display: 'inline-flex', alignItems: 'center', gap: 5, fontSize: 12, padding: '4px 12px', borderRadius: 20, background: cardBg, border: '1px solid var(--paper-3)', color: 'var(--ink-2)', boxShadow: '1px 1px 3px rgba(0,0,0,0.06)' }}>
                  {a}
                  <button onClick={() => removeFromList('actors',i)} style={{ fontSize: 9, color: 'var(--ink-4)', background: 'none', border: 'none', cursor: 'pointer', padding: 0 }} onMouseEnter={e=>e.currentTarget.style.color='var(--red)'} onMouseLeave={e=>e.currentTarget.style.color='var(--ink-4)'}>✕</button>
                </span>
              ))}
            </div>
            <div style={{ display: 'flex', gap: 6 }}>
              <input value={newActor} onChange={e=>setNewActor(e.target.value)} onKeyDown={e=>e.key==='Enter'&&addToList('actors',newActor,setNewActor)}
                placeholder="Add actor…" style={{ flex: 1, padding: '6px 10px', fontSize: 12, borderRadius: 6 }} />
              <button onClick={()=>addToList('actors',newActor,setNewActor)} style={{ fontSize: 11, padding: '6px 12px', borderRadius: 6, background: 'var(--accent)', color: 'var(--paper-card)', border: 'none', cursor: 'pointer' }}>Add</button>
            </div>
          </div>

          {/* Causes */}
          <div style={{ marginBottom: 20 }}>
            <SL>Causes / contributing factors</SL>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 5, marginBottom: 8 }}>
              {(inv.causes||[]).map((c,i) => (
                <div key={i} style={{ display: 'flex', gap: 8, background: cardBg, border: '1px solid var(--paper-3)', borderRadius: 6, padding: '7px 10px', boxShadow: '1px 1px 3px rgba(0,0,0,0.05)' }}>
                  <span style={{ color: invType.color, fontWeight: 900, flexShrink: 0, fontSize: 14 }}>·</span>
                  <span style={{ flex: 1, fontSize: 13, color: 'var(--ink)', lineHeight: 1.55 }}>{c}</span>
                  <button onClick={()=>removeFromList('causes',i)} style={{ fontSize: 9, color: 'var(--ink-4)', background: 'none', border: 'none', cursor: 'pointer', padding: 0 }} onMouseEnter={e=>e.currentTarget.style.color='var(--red)'} onMouseLeave={e=>e.currentTarget.style.color='var(--ink-4)'}>✕</button>
                </div>
              ))}
            </div>
            <div style={{ display: 'flex', gap: 6 }}>
              <input value={newCause} onChange={e=>setNewCause(e.target.value)} onKeyDown={e=>e.key==='Enter'&&addToList('causes',newCause,setNewCause)}
                placeholder="Add a cause or factor…" style={{ flex: 1, padding: '6px 10px', fontSize: 12, borderRadius: 6 }} />
              <button onClick={()=>addToList('causes',newCause,setNewCause)} style={{ fontSize: 11, padding: '6px 12px', borderRadius: 6, background: 'var(--accent)', color: 'var(--paper-card)', border: 'none', cursor: 'pointer' }}>Add</button>
            </div>
          </div>

          {/* Analysis */}
          <div style={{ marginBottom: 20 }}>
            <SL>Analysis</SL>
            <div style={{ background: cardBg, border: '1px solid var(--paper-3)', borderRadius: 8, boxShadow: '1px 2px 6px rgba(0,0,0,0.06)' }}>
              <SimpleEditor value={inv.analysis||''} onChange={val=>set('analysis',val)}
                placeholder="Develop your analysis — what do the sources show? What patterns emerge? Where does the evidence lead?" />
            </div>
          </div>

          {/* ── VERDICT ──────────────────────────────────── */}
          <div>
            <SL>Verdict</SL>
            <div style={{ background: isDark?'#1e2818':'#f4faf0', border: '2px solid #2e7d5e44', borderRadius: 8, padding: '14px 16px', boxShadow: '1px 2px 6px rgba(0,0,0,0.06)', position: 'relative' }}>
              {/* Wax seal decoration */}
              <div style={{ position: 'absolute', top: -10, right: 14, width: 22, height: 22, borderRadius: '50%', background: '#2e7d5e', border: '2px solid #1a5c3a', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 10, color: '#fff' }}>⊛</div>
              <div style={{ fontSize: 10, fontWeight: 700, color: '#2e7d5e', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 8 }}>Final verdict</div>
              <InlineText value={inv.verdict||''} onChange={val=>{ set('verdict',val); if(val.trim()) { const entry={id:uuidv4(),type:'verdict',note:val.trim().slice(0,120),createdAt:new Date().toISOString()}; onUpdate({...inv,verdict:val,custodyLog:[...(inv.custodyLog||[]),entry],updatedAt:new Date().toISOString()}); } }}
                placeholder="Based on the evidence, I conclude…" multiline
                style={{ fontSize: 13, color: 'var(--ink)', lineHeight: 1.75, fontStyle: inv.verdict?'normal':'italic' }} />
              {!inv.verdict && <div style={{ fontSize: 10, color: 'var(--ink-4)', marginTop: 8, fontStyle: 'italic' }}>Click above to record your verdict. This will be logged in the chain of custody.</div>}
            </div>
          </div>

          {/* Tags */}
          <div style={{ marginTop: 20 }}>
            <SL>Tags</SL>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 8 }}>
              {(inv.tags||[]).map((tag,i) => <TagChip key={i} tag={tag} onRemove={()=>removeFromList('tags',i)} onViewTimeline={onViewTimeline} />)}
            </div>
            <div style={{ display: 'flex', gap: 6 }}>
              <input value={newTag} onChange={e=>setNewTag(e.target.value)}
                onKeyDown={e=>(e.key==='Enter'||e.key===',')&&addToList('tags',newTag.replace(',','').toLowerCase(),setNewTag)}
                placeholder="Add tag…" style={{ flex: 1, padding: '6px 10px', fontSize: 12, borderRadius: 6 }} />
              <button onClick={()=>addToList('tags',newTag.replace(',','').toLowerCase(),setNewTag)} style={{ fontSize: 11, padding: '6px 12px', borderRadius: 6, background: 'var(--accent)', color: 'var(--paper-card)', border: 'none', cursor: 'pointer' }}>Add</button>
            </div>
          </div>
        </div>

        {/* COL 2 — Evidence (book notes) */}
        <div style={{ overflowY: 'auto', padding: '18px 14px', borderRight: `1px solid ${invType.color}22`, background: isDark?'#1e1b16':'#f7f3e9' }}>
          <SL action={
            <button onClick={()=>setAddingBook(s=>!s)}
              style={{ fontSize: 10, color: 'var(--ink-4)', background: 'none', border: '1px solid var(--paper-3)', borderRadius: 5, padding: '2px 8px', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
              {addingBook?'done':'+ source'}
            </button>
          }>Evidence</SL>
          {addingBook && (
            <div style={{ marginBottom: 12, display: 'flex', flexWrap: 'wrap', gap: 5 }}>
              {books.map(b => { const linked=(inv.bookIds||[]).includes(b.id); return (
                <button key={b.id} onClick={()=>toggleBook(b.id)}
                  style={{ fontSize: 10, padding: '3px 10px', borderRadius: 20, cursor: 'pointer', border:`1px solid ${linked?b.color:'var(--paper-3)'}`, background:linked?b.color+'22':'transparent', color:linked?b.color:'var(--ink-3)' }}>
                  {linked?'✓ ':''}{b.title}
                </button>
              ); })}
            </div>
          )}
          {linkedBooks.length === 0 ? (
            <div style={{ fontSize: 12, color: 'var(--ink-4)', fontStyle: 'italic', textAlign: 'center', padding: '24px 0', lineHeight: 1.65 }}>No sources yet.<br />Click "+ source" to add.</div>
          ) : linkedBooks.map((book,idx) => {
            const bn = (inv.bookNotes||[]).find(n=>n.bookId===book.id)||{bookId:book.id,quote:'',note:''};
            return (
              <div key={book.id} style={{ background: cardBg, border:`1px solid ${book.color}33`, borderRadius: 8, padding: '12px 13px', marginBottom: 12, boxShadow: '1px 2px 6px rgba(0,0,0,0.07)', position: 'relative' }}>
                <div style={{ position: 'absolute', top: -8, right: 10, fontSize: 9, padding: '1px 8px', background: book.color, color: '#fff', borderRadius: 4, fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.08em' }}>
                  EXHIBIT {String.fromCharCode(65+idx)}
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 8, paddingBottom: 7, borderBottom:`1px solid ${book.color}22` }}>
                  <div style={{ width: 8, height: 8, borderRadius: '50%', background: book.color }} />
                  <span style={{ fontSize: 11, fontWeight: 500, color: book.color, fontStyle: 'italic', flex: 1 }}>{book.title}</span>
                  <button onClick={()=>toggleBook(book.id)} style={{ fontSize: 9, color: 'var(--ink-4)', background: 'none', border: 'none', cursor: 'pointer' }} onMouseEnter={e=>e.currentTarget.style.color='var(--red)'} onMouseLeave={e=>e.currentTarget.style.color='var(--ink-4)'}>remove</button>
                </div>
                <div style={{ fontSize: 9, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 4 }}>Quote</div>
                <textarea value={bn.quote||''} onChange={e=>updateBookNote(book.id,'quote',e.target.value)}
                  placeholder="A passage from this source…" rows={2}
                  style={{ width: '100%', resize: 'vertical', padding: '5px 7px', fontSize: 11, borderRadius: 5, fontStyle: 'italic', color: 'var(--ink-2)', background: isDark?'#1a1814':'#fff', border: '1px solid var(--paper-3)', fontFamily: 'var(--font-serif)', marginBottom: 7 }} />
                <div style={{ fontSize: 9, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 4 }}>Field note</div>
                <textarea value={bn.note||''} onChange={e=>updateBookNote(book.id,'note',e.target.value)}
                  placeholder="How does this author discuss this case?" rows={2}
                  style={{ width: '100%', resize: 'vertical', padding: '5px 7px', fontSize: 11, borderRadius: 5, color: 'var(--ink)', background: isDark?'#1a1814':'#fff', border: '1px solid var(--paper-3)', fontFamily: 'var(--font-serif)' }} />
              </div>
            );
          })}

          {/* ── CONTRADICTIONS ─────────────────────────── */}
          <div style={{ marginTop: 18 }}>
            <SL action={
              <button onClick={()=>setShowContraForm(s=>!s)}
                style={{ fontSize: 10, color: '#c0392b', background: 'none', border: '1px solid #c0392b44', borderRadius: 5, padding: '2px 8px', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
                {showContraForm?'cancel':'+ contradiction'}
              </button>
            }>Contradictions</SL>

            {showContraForm && (
              <div style={{ background: cardBg, border: '1px solid #c0392b33', borderRadius: 7, padding: '10px 12px', marginBottom: 10 }}>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 6, marginBottom: 6 }}>
                  <input value={newContra.sourceA} onChange={e=>setNewContra(c=>({...c,sourceA:e.target.value}))}
                    placeholder="Source A…" style={{ padding: '5px 8px', fontSize: 11, borderRadius: 5 }} />
                  <input value={newContra.sourceB} onChange={e=>setNewContra(c=>({...c,sourceB:e.target.value}))}
                    placeholder="Source B…" style={{ padding: '5px 8px', fontSize: 11, borderRadius: 5 }} />
                </div>
                <textarea value={newContra.claim} onChange={e=>setNewContra(c=>({...c,claim:e.target.value}))}
                  placeholder="What do they contradict each other on?" rows={2}
                  style={{ width: '100%', padding: '5px 8px', fontSize: 12, borderRadius: 5, resize: 'vertical', fontFamily: 'var(--font-serif)', border: '1px solid var(--paper-3)', marginBottom: 6 }} />
                <button onClick={addContradiction}
                  style={{ fontSize: 11, padding: '5px 14px', borderRadius: 6, background: '#c0392b', color: '#fff', border: 'none', cursor: 'pointer' }}>
                  Record contradiction
                </button>
              </div>
            )}

            {(inv.contradictions||[]).length === 0 && !showContraForm && (
              <div style={{ fontSize: 11, color: 'var(--ink-4)', fontStyle: 'italic', textAlign: 'center', padding: '10px 0' }}>No contradictions noted yet.</div>
            )}
            {(inv.contradictions||[]).map(item => (
              <ContradictionCard key={item.id} item={item} onDelete={removeContradiction} />
            ))}
          </div>
        </div>

        {/* COL 3 — Chain of custody */}
        <div style={{ overflowY: 'auto', padding: '18px 14px', borderRight: `1px solid ${invType.color}22`, background: isDark?'#1c1a15':'#f5f0e4' }}>
          <SL>Chain of custody</SL>
          <div style={{ fontSize: 10, color: 'var(--ink-4)', fontStyle: 'italic', lineHeight: 1.6, marginBottom: 14 }}>
            A chronological log of how your argument developed — evidence added, positions revised, contradictions found. Useful for tracing your reasoning when writing a thesis.
          </div>

          {/* Add log entry */}
          <div style={{ background: cardBg, border: '1px solid var(--paper-3)', borderRadius: 7, padding: '10px 12px', marginBottom: 16 }}>
            <select value={newLogType} onChange={e=>setNewLogType(e.target.value)}
              style={{ width: '100%', padding: '5px 8px', fontSize: 11, borderRadius: 5, marginBottom: 6, fontFamily: 'var(--font-mono)' }}>
              {Object.entries(LOG_TYPES).filter(([k])=>k!=='contradiction').map(([k,v]) => (
                <option key={k} value={k}>{v.icon} {v.label}</option>
              ))}
            </select>
            <textarea value={newLogNote} onChange={e=>setNewLogNote(e.target.value)}
              onKeyDown={e=>e.key==='Enter'&&e.metaKey&&addLogEntry()}
              placeholder="Log a step in your reasoning… (⌘↵ to save)"
              rows={2}
              style={{ width: '100%', resize: 'none', padding: '5px 8px', fontSize: 12, borderRadius: 5, fontFamily: 'var(--font-serif)', border: '1px solid var(--paper-3)', marginBottom: 6 }} />
            <button onClick={addLogEntry}
              style={{ fontSize: 11, padding: '5px 14px', borderRadius: 6, background: 'var(--accent)', color: 'var(--paper-card)', border: 'none', cursor: 'pointer', width: '100%' }}>
              Add to log
            </button>
          </div>

          {/* Log entries — newest first */}
          {(inv.custodyLog||[]).length === 0 ? (
            <div style={{ fontSize: 11, color: 'var(--ink-4)', fontStyle: 'italic', textAlign: 'center', padding: '12px 0' }}>No entries yet.</div>
          ) : [...(inv.custodyLog||[])].reverse().map(entry => (
            <LogEntry key={entry.id} entry={entry} />
          ))}
        </div>

        {/* COL 4 — Related timeline events */}
        <div style={{ overflowY: 'auto', padding: '18px 14px' }}>
          <SL action={
            relatedEvents.length > 0 && onViewTimeline && (
              <button onClick={()=>onViewTimeline(inv.tags?.[0])}
                style={{ fontSize: 10, color: 'var(--accent)', background: 'none', border: 'none', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
                view all →
              </button>
            )
          }>Related events</SL>
          {relatedEvents.length === 0 ? (
            <div style={{ fontSize: 11, color: 'var(--ink-4)', fontStyle: 'italic', textAlign: 'center', padding: '24px 0', lineHeight: 1.65 }}>
              No matching events.<br />Add tags to timeline events that match this case.
            </div>
          ) : relatedEvents.map(ev => {
            const parsed = parseEventDate(ev.dateRaw);
            const evBooks = books.filter(b=>(ev.bookIds||[]).includes(b.id));
            const sharedTags = (ev.tags||[]).filter(t=>(inv.tags||[]).includes(t));
            return (
              <div key={ev.id} onClick={()=>onViewTimeline?.(sharedTags[0]||inv.tags?.[0])}
                style={{ background: cardBg, border: '1px solid var(--paper-3)', borderRadius: 7, padding: '10px 11px', marginBottom: 8, cursor: 'pointer', boxShadow: '1px 1px 4px rgba(0,0,0,0.05)' }}
                onMouseEnter={e=>{ e.currentTarget.style.borderColor='var(--accent-2)'; e.currentTarget.style.boxShadow='var(--shadow-sm)'; }}
                onMouseLeave={e=>{ e.currentTarget.style.borderColor='var(--paper-3)'; e.currentTarget.style.boxShadow='1px 1px 4px rgba(0,0,0,0.05)'; }}>
                <div style={{ fontSize: 9, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', marginBottom: 2 }}>{parsed.display||ev.dateRaw}</div>
                <div style={{ fontSize: 12, fontWeight: 500, color: 'var(--ink)', lineHeight: 1.35, marginBottom: evBooks.length?4:0 }}>{ev.title}</div>
                {evBooks.length>0&&<div style={{ display:'flex',gap:4,flexWrap:'wrap',marginBottom:4 }}>{evBooks.map(b=><span key={b.id} style={{ display:'flex',alignItems:'center',gap:3,fontSize:9,color:b.color,fontStyle:'italic' }}><div style={{ width:4,height:4,borderRadius:'50%',background:b.color }} />{b.title}</span>)}</div>}
                <div style={{ display:'flex',gap:4,flexWrap:'wrap' }}>{sharedTags.map(t=><span key={t} style={{ fontSize:9,padding:'1px 6px',borderRadius:8,background:'var(--accent-light)',color:'var(--accent)',fontFamily:'var(--font-mono)',fontStyle:'normal' }}>#{t}</span>)}</div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}
